import asyncio
import inspect
from contextlib import contextmanager

import anyio
from starlette.testclient import _TestClientTransport, httpx

class Portal:
    def call(self, func, *args):
        if func is anyio.Event:
            return asyncio.Event()
        value = func(*args)
        if inspect.isawaitable(value):
            return asyncio.run(value)
        return value

@contextmanager
def portal_factory():
    yield Portal()

async def app(scope, receive, send):
    template = scope[\"state\"][\"template\"]
    context = scope[\"state\"][\"context\"]
    await send({\"type\": \"http.response.debug\", \"info\": {
        \"template\": template,
        \"context\": context,
        \"custom\": {\"nested\": True},
    }})
    await send({\"type\": \"http.response.start\", \"status\": 200, \"headers\": []})
    await send({\"type\": \"http.response.body\", \"body\": b\"ok\"})

template = object()
context = {\"request\": object()}
transport = _TestClientTransport(
    app,
    portal_factory,
    client=(\"testclient\", 50000),
    app_state={\"template\": template, \"context\": context},
)
response = transport.handle_request(httpx.Request(\"GET\", \"http://testserver/\"))
assert response.extensions[\"http.response.debug\"] == {
    \"template\": template,
    \"context\": context,
    \"custom\": {\"nested\": True},
}
assert response.template is template
assert response.context is context
print(\"direct transport probe passed\")
